#include <vector>
#include <numeric>

class Solution {
public:
    int countPartitions(std::vector<int>& nums) {
        long long s = std::accumulate(nums.begin(), nums.end(), 0LL);
        return (s % 2 == 0) ? (int)nums.size() - 1 : 0;
    }
};

class Solution {
    public int countPartitions(int[] nums) {
        long s = 0;
        for (int x : nums) s += x;
        return (s % 2 == 0) ? nums.length - 1 : 0;
    }
}

var countPartitions = function(nums) {
    let s = 0;
    for (let i = 0; i < nums.length; i++) s += nums[i];
    return (s % 2 === 0) ? nums.length - 1 : 0;
};
